package com.android_dev.rentaly_management.Fragment;
import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.appcompat.app.AlertDialog;import androidx.fragment.app.Fragment;import androidx.navigation.fragment.NavHostFragment;import com.android_dev.rentaly_management.Apis.ApiClient;import com.android_dev.rentaly_management.DTO.*;import com.android_dev.rentaly_management.R;import java.util.*;import retrofit2.*;
public class AnnouncementFragment extends Fragment{private final List<Announcement> items=new ArrayList<>();private final List<UserTenant> users=new ArrayList<>();private ArrayAdapter<Announcement> adapter;private ProgressBar loading;private TextView empty;
@Nullable public View onCreateView(@NonNull LayoutInflater i,ViewGroup c,Bundle b){View v=i.inflate(R.layout.fragment_announcement,c,false);loading=v.findViewById(R.id.announcement_loading);empty=v.findViewById(R.id.announcement_empty);v.findViewById(R.id.announcement_back).setOnClickListener(x->NavHostFragment.findNavController(this).navigateUp());v.findViewById(R.id.announcement_add).setOnClickListener(x->loadUsers(null));adapter=new ArrayAdapter<Announcement>(requireContext(),R.layout.item_announcement,R.id.announcement_item_content,items){public View getView(int p,View q,@NonNull ViewGroup g){View r=super.getView(p,q,g);Announcement a=getItem(p);((TextView)r.findViewById(R.id.announcement_item_content)).setText(a.content);((TextView)r.findViewById(R.id.announcement_item_meta)).setText(("SENTED".equalsIgnoreCase(a.status)?"Đã gửi":"Bản nháp")+" | Người nhận: "+(a.recipient_ids==null?0:a.recipient_ids.size()));return r;}};((ListView)v.findViewById(R.id.announcement_list)).setAdapter(adapter);load();return v;}
private void load(){loading.setVisibility(View.VISIBLE);ApiClient.api.announcements().enqueue(new Callback<List<Announcement>>(){public void onResponse(Call<List<Announcement>>c,Response<List<Announcement>>r){loading.setVisibility(View.GONE);if(r.isSuccessful()&&r.body()!=null){items.clear();items.addAll(r.body());adapter.notifyDataSetChanged();empty.setVisibility(items.isEmpty()?View.VISIBLE:View.GONE);}else error("Không thể tải thông báo");}public void onFailure(Call<List<Announcement>>c,Throwable t){loading.setVisibility(View.GONE);error("Không thể kết nối đến máy chủ");}});}
private void loadUsers(Announcement old){ApiClient.api.managedUsers(null).enqueue(new Callback<List<UserTenant>>(){public void onResponse(Call<List<UserTenant>>c,Response<List<UserTenant>>r){if(r.isSuccessful()&&r.body()!=null){users.clear();users.addAll(r.body());form(old);}else error("Không thể tải danh sách người nhận");}public void onFailure(Call<List<UserTenant>>c,Throwable t){error("Không thể kết nối đến máy chủ");}});}
private void form(Announcement old){View v=getLayoutInflater().inflate(R.layout.dialog_create_announcement,null);EditText content=v.findViewById(R.id.announcement_form_content),type=v.findViewById(R.id.announcement_form_type);ListView recipients=v.findViewById(R.id.announcement_form_recipients);CheckBox send=v.findViewById(R.id.announcement_form_send);List<String> labels=new ArrayList<>();for(UserTenant user:users)labels.add(user.displayName());recipients.setAdapter(new ArrayAdapter<String>(requireContext(),android.R.layout.simple_list_item_multiple_choice,labels));if(old!=null){content.setText(old.content);type.setText(old.announcement_type);send.setChecked("SENTED".equalsIgnoreCase(old.status));for(int i=0;i<users.size();i++)if(old.recipient_ids!=null&&old.recipient_ids.contains(users.get(i).getUser_id()))recipients.setItemChecked(i,true);}new AlertDialog.Builder(requireContext()).setTitle(old==null?"Tạo thông báo":"Sửa thông báo").setView(v).setNegativeButton("Hủy",null).setPositiveButton("Lưu",(d,w)->{List<UUID> ids=new ArrayList<>();for(int i=0;i<users.size();i++)if(recipients.isItemChecked(i))ids.add(users.get(i).getUser_id());if(content.getText().toString().trim().isEmpty()||ids.isEmpty()){error("Cần nhập nội dung và chọn người nhận");return;}AnnouncementRequest q=new AnnouncementRequest(content.getText().toString().trim(),type.getText().toString().trim(),send.isChecked(),ids);Call<Announcement> call=old==null?ApiClient.api.createAnnouncement(q):ApiClient.api.updateAnnouncement(old.announcement_id.toString(),q);call.enqueue(new Callback<Announcement>(){public void onResponse(Call<Announcement>c,Response<Announcement>r){if(r.isSuccessful()){error("Đã lưu thông báo");load();}else error("Không thể lưu thông báo");}public void onFailure(Call<Announcement>c,Throwable t){error("Không thể kết nối đến máy chủ");}});}).show();}
private void error(String s){Toast.makeText(requireContext(),s,Toast.LENGTH_LONG).show();}}
